-- =====================================================================
-- 开源安全评分看板 · 指标明细展示配置（dm_rd_efc_security_metric_detail_conf）
-- 作用：18 指标的明细页展示配置（summary 数字条 / 失败卡片 / 明细表格列 /
--       文案 / 配色规则）全部存于本表，改文案/列名/颜色规则只需 UPDATE 数据，
--       无需发版。服务端引擎按本表配置渲染，表内缺失时回退 classpath 内置默认。
-- 生成：ai-assisted 2026-09-28，内容依据 docs/0912/明细数据设计freemarker模版/ 21 个原型
-- 更新：ai-assisted 2026-10-14，基线 = 生产 DB 实测快照；全量注入 rule（判定规则）与 definition（指标定义）展示节点
-- 可重复执行：UNIQUE KEY(metric_code)，重跑等效覆盖（Doris Unique 模型后写覆盖先写）
--
-- conf_json DSL 速查（引擎实现以此为准）：
--   取值表达式：$path（raw 字段/行字段，查找顺序 行→根上下文）、$this（迭代元素自身）、
--              $s.key（summary 计算值，hidden:true 的项不渲染但可引用）、$p.name（params 常量）、
--              #tpl:文本 {field}（模板，可引用 {s.x}/{p.x}/raw 字段）、
--              #bool:$f:是:否、#ifnull:$f:兜底、#str:$f（对象转字符串）、#ext:$path（取后缀）、
--              #count:$arr、#qcount:$arr:k=v / k!=v（等值/不等过滤计数，多条件逗号分隔）、
--              #sumlen:$arr.sub（嵌套数组长度求和）、#join:$arr:分隔符、#join:$arr:key:分隔符、
--              #joinobj:$obj:分隔符（对象转 k: v 拼接）、
--              #add:$a,$b、#sub:$a,$b、#mul:$a,$b、#pct:$a,$b（百分比取1位）、
--              #sat:$a,$b,$c（布尔真值计数）、
--              #href:https://...（链接模板，引擎统一过 gitcode.com 白名单）
--   level 表达式（配色）：固定值 success/warning/error/critical/na、
--              #map:$f:k1:v1,k2:v2,*:默认、#gt/$a:$b:level 与 #lt:#ge:#eq（比较，操作数可为路径或字面量）、
--              #bool:$f:levelT:levelF（空串=无色）
--   结构约定：summary[{key?,label,value,level?,hidden?}]；
--             failItems 为固定卡数组（卡可带 when:"path op value" 条件，op ∈ = != > >= < <=，
--               操作数 = summary key / raw 字段 / @p.xxx 参数）或 {from,filter{f:v|f:!=v},card{...}}；
--             failNote/failEmptyText/dataNote 为 #tpl 或纯文本；groups 空数组时前端整块不渲染，
--             emptyHint 为占位提示文案（数据未采集场景）。
-- =====================================================================

-- 1. 建表（若已手工建过可跳过）
CREATE TABLE IF NOT EXISTS dm_rd_efc_security_metric_detail_conf (
    metric_code    VARCHAR(64)  NOT NULL COMMENT '指标码，关联 dm_rd_efc_security_metric_conf.metric_code（如 VULNS/MAINTAINED）',
    conf_json      STRING       NOT NULL COMMENT '明细展示配置JSON：summary/failNote/failItems/groups 的mini-DSL（改文案/列名/配色规则只需UPDATE此字段）',
    enabled        TINYINT      NOT NULL DEFAULT 1 COMMENT '1=启用本配置 0=停用（服务自动回退内置默认配置）',
    updated_by     VARCHAR(64)           COMMENT '最近修改人（审计留痕）',
    updated_at     DATETIME              COMMENT '最近修改时间（审计留痕）'
) ENGINE=OLAP
UNIQUE KEY(metric_code)
COMMENT '安全合规评分看板·指标明细展示配置表（手动维护，与 metric_conf 一行一指标对应）'
DISTRIBUTED BY HASH(metric_code) BUCKETS 1;

-- 2. 初始化 18 行配置（按 metric_conf.display_order）

-- 01 LICENSE 开源许可证（阶梯计分，ladder 数组由服务端按得分推导注入）

-- 2. 初始化 18 行配置（按 metric_conf.display_order）
-- 01 LICENSE 开源许可证（阶梯计分，ladder 数组由服务端按得分推导注入）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('LICENSE',
'{"summary":[{"key":"spdx","label":"SPDX 标识","value":"#join:$detected_licenses:spdx:、","level":"#gt:$detected_licenses:0:success"},{"key":"reached","hidden":true,"value":"#qcount:$ladder:status=达成"},{"key":"missed","hidden":true,"value":"#qcount:$ladder:status=未达成"},{"label":"当前档位","value":"#tpl:{score} 分","level":"#eq:$score:10:success"},{"label":"已达成台阶","value":"#tpl:{s.reached} / 4"},{"label":"未达成","value":"#tpl:{s.missed}","level":"#gt:$s.missed:0:error"},{"label":"差异对照文件","value":"$license_path","when":"diffCount>0"}],"failNote":"#tpl:递进计分：逐台阶累加（5 → 8 → 9 → 10），无逐条扣分（故卡片不显示扣分值）　｜　当前 {score} 分","failEmptyText":"全部满足：四个台阶全部达成，得 10 分","dataNote":"阶梯计分（递进累加）：有许可证 5 分 → 模板一致 +3 分（8 分）→ copyright 年份与责任人替换正确 +1 分（9 分）→ OSI/FSF 认证 +1 分（10 分）；无许可证 0 分。⚠ 阶梯是递进的：前置台阶未达成时，后续台阶不再判定（显示为未评估）。⚠ 多许可证文件夹仓（如 LICENSES/ 下多个协议文件）：每个文件都参与全部台阶判定，全部达标该台阶才算达成，仓得分取各文件最低分；未达台阶的判定依据会点名具体未达标文件。⚠ 模板不一致时明细自动展示「模板差异对照」：左列为官方模板要求，右列为你的 LICENSE 实际内容，行号为差异内容在你的 LICENSE 文件内的行号；红色行 = 模板有而你的文件缺失的内容，琥珀色行 = 与模板不一致或多出的内容；多许可证文件夹仓以得分最低（瓶颈）文件为对照对象。本指标无 NA 条件，无许可证记 0 分并参与汇聚（0 分进分母，NA 剔除分子分母）。","failItems":{"from":"$ladder","filter":{"status":"!=达成,!=未评估"},"card":{"title":"#tpl:台阶「{name}」{status}","fields":[{"label":"台阶","value":"$name"},{"label":"判定","value":"$status","level":"#map:$status:未达成:error,*:na"},{"label":"判定依据","value":"$why"}],"reason":"#tpl:{why}","searchText":"#tpl:{name} {status} {why}"}},"groups":[{"key":"ladder","label":"计分阶梯","columns":[{"label":"阶梯","key":"step","type":"number"},{"label":"台阶","key":"name","type":"text"},{"label":"是否达成","key":"ok","type":"text"},{"label":"判定依据","key":"why","type":"text"}],"rowsFrom":"$ladder","cellOf":{"step":{"text":"$step"},"name":{"text":"$name"},"ok":{"text":"$status","level":"#map:$status:达成:success,未达成:error,*:na"},"why":{"text":"$why"}},"searchText":"#tpl:{step} {name} {status} {why}"},{"key":"diff","label":"模板差异对照","when":"diffCount>0","columns":[{"label":"行号","key":"line","type":"text"},{"label":"官方模板要求","key":"tpl","type":"wrap"},{"label":"你的 LICENSE 实际内容","key":"file","type":"wrap"}],"rowsFrom":"$diffRows","rowLevel":"#map:$status:del:error,add:warning,mod:warning","cellOf":{"line":{"text":"$line"},"tpl":{"text":"$tpl"},"file":{"text":"$file"}},"searchText":"#tpl:{line} {tpl} {file}"}],"emptyHint":"许可证与官方模板一致（或本批次尚未重新采集），无模板差异对照，仅展示计分阶梯","rule":{"brief":"检查仓库根目录（或 license 目录）下的 LICENSE 文件：是否有许可证、格式是否符合官方模板、版权年份和责任人是否填写正确、是否通过 OSI/FSF 开源认证；多许可证文件夹仓逐文件判定，全部达标才算达标。","formula":"阶梯计分（递进累加）：无许可证 0 → 有许可证 5 → 模板一致 +3（8 分）→ 版权正确 +1（9 分）→ OSI/FSF 认证 +1（10 分）；前置台阶未达成时，后续台阶不再评估；多许可证文件夹仓得分取各文件最低分","conditions":[{"label":"无 LICENSE 文件","value":"0 分（有效低分，不是不参评）"},{"label":"有许可证","value":"5 分（基础分）"},{"label":"格式符合官方模板","value":"+3 分 → 8 分"},{"label":"版权年份和责任人正确","value":"+1 分 → 9 分"},{"label":"通过 OSI/FSF 认证","value":"+1 分 → 10 分"},{"label":"多许可证文件夹（如 LICENSES/ 双协议）","value":"每个文件全台阶判定，全部达标该台阶才达成，仓得分取各文件最低分"},{"label":"模板不一致时","value":"明细自动展示官方模板 vs 你的 LICENSE 的并排差异对照：红色行 = 模板有而文件缺失，琥珀色行 = 内容不一致或多出，行号 = LICENSE 文件内行号"}],"naCondition":"无，本指标恒有得分。","notes":[]}}',
1, 'ai-assisted', NOW());

-- 02 COPYRIGHT 版权合规
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('COPYRIGHT',
'{"rule":{"brief":"逐个检查源码文件（.go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat，test/tests 目录除外）的文件头版权声明，是否与仓库 LICENSE 协议对应的官方版权模板一致。","formula":"得分 = 10 − 0.2 × 不合格文件数（最低 0 分，50 个扣完，目标文件少于 50 个按比例扣分）","conditions":[{"label":"合格","value":"文件头含规范版权行（年份 + Huawei），且正文与模板匹配"},{"label":"不合格","value":"无文件头 / 无版权行 / 版权行不规范 / 正文与模板不匹配"},{"label":"比对模板","value":"1、LICENSE内置Copyright模板 2、自定义Copyright模板（可联系运维人员配置）"}],"naCondition":"仓库无 LICENSE 文件（或不可读）、或没有任何目标类型源码文件时，本指标不参评。","notes":[]},"definition":{"brief":"衡量仓库源码文件头的版权声明是否与 LICENSE 协议对应的官方版权模板一致，即「代码带着正确的版权头发布」。","purpose":"版权声明是权利主张的法律凭据；文件头缺失或不规范会削弱权利主张，也影响代码溯源与合规审计。","details":[{"label":"数据来源","value":"文件扫描脚本逐文件比对（结果存版权合规问题文件清单）"},{"label":"比对模板","value":"1、LICENSE内置Copyright模板 2、自定义Copyright模板（可联系运维人员配置）"},{"label":"检查范围","value":".go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat 源码文件，test/tests 目录除外"}],"notes":[]},"summary":[{"key":"total","label":"目标文件总数","value":"$target_file_count"},{"key":"matched","label":"含声明","value":"$matched_count","level":"#gt:$matched_count:0:success"},{"key":"rate","hidden":true,"value":"#pct:$matched_count,$target_file_count"},{"key":"miss","hidden":true,"value":"#sub:$target_file_count,$matched_count"},{"label":"含声明率","value":"#tpl:{s.rate}%","level":"#lt:$matched_count:$target_file_count:warning"},{"label":"超大文件跳过","value":"#ifnull:$oversize_file_count:0","level":"na"}],"failNote":"#tpl:评分：10 − 0.2 × 不合格文件数 {s.miss} = {score}　｜　每个不合格文件扣 0.2 分，扣完为止（50 个扣完 10 分，目标文件少于 50 个时按比例扣分）","failEmptyText":"全部满足：所有目标后缀文件均检出合规的 copyright 声明","dataNote":"判定正则为「Copyright (c) 年份 Huawei Technologies Co.」有空格写法。超 8MB / 不可读文件不计入目标文件数（既不算合格也不算不合格）。未检出与内容不匹配的逐文件明细暂未采集，明细仅提供按后缀统计。","failItems":[{"when":"matched_count<target_file_count","title":"存在未检出版权声明的文件","fields":[{"label":"目标文件总数","value":"$target_file_count"},{"label":"含声明","value":"$matched_count"},{"label":"不合格文件数","value":"#sub:$target_file_count,$matched_count","level":"error"},{"label":"含声明率","value":"#tpl:{s.rate}%","level":"warning"}],"reason":"#tpl:未满足：{target_file_count} 个目标后缀文件中 {s.miss} 个不合格（未检出合规 copyright 声明），每个扣 0.2 分","searchText":"版权头 未检出"}],"groups":[{"key":"ext","label":"按后缀统计","columns":[{"label":"后缀","key":"ext","type":"text"},{"label":"目标文件数","key":"total","type":"number"},{"label":"含版权头","key":"matched","type":"number"},{"label":"缺失","key":"miss","type":"number"},{"label":"匹配率","key":"rate","type":"text"}],"rowsFrom":"$by_ext","cellOf":{"ext":{"text":"$ext"},"total":{"text":"$file_count"},"matched":{"text":"$matched_count","level":"#gt:$matched_count:0:success"},"miss":{"text":"#sub:$file_count,$matched_count","level":"#lt:$matched_count:$file_count:warning"},"rate":{"text":"#pct:$matched_count,$file_count"}},"searchText":"#tpl:{ext} {file_count} {matched_count}"}]}',
1, 'ai-assisted', NOW());

-- 03 DANGEROUS_WF 危险工作流（二元判定）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('DANGEROUS_WF',
'{"rule":{"brief":"检查 .gitcode/workflows 下 CI 配置文件中的两类危险写法：① 不可信代码（是否默认安全），存在显式配置 “allow-unsafe-pr-checkout: true”；② 不可信上下文变量（外部可控变量），详见下表。","formula":"发现任意一处危险模式 = 0 分；全部干净 = 10 分","conditions":[{"label":"①不可信代码（是否默认安全）","value":"存在显式配置 “allow-unsafe-pr-checkout: true”"},{"label":"②不可信上下文变量（外部可控变量）","value":"1）atomgit.event.issue.title；2）atomgit.event.pull_request.title；3）atomgit.event.pull_request.body；4）atomgit.event.comment.body；5）atomgit.event.commits[].message；6）atomgit.head_ref"}],"notes":[]},"definition":{"brief":"衡量 CI workflow 配置的安全水位：是否存在允许检出不可信 PR 代码、或在脚本中直接引用不可信上下文变量等危险写法。","purpose":"workflow 凭据权限高，恶意 PR 可借不可信输入注入命令窃取令牌，是开源供应链攻击的常见入口；本指标用于提前暴露这类可被利用的配置。","details":[{"label":"数据来源","value":".gitcode/workflows 目录 CI 配置文件扫描"},{"label":"检查对象","value":"allow-unsafe-pr-checkout 显式开启、脚本步骤中直接引用 PR 标题/描述/评论等不可信上下文变量"},{"label":"参考标准","value":"对齐 OSSF Scorecard dangerous-workflow 检查项"}],"notes":[]},"summary":[{"key":"files","label":"workflow 文件数","value":"$wf_file_count"},{"key":"hits","label":"命中危险模式","value":"#qcount:$findings:reason!=ok","level":"#gt:$s.hits:0:error"},{"key":"unsafeCnt","hidden":true,"value":"#qcount:$findings:unsafe_checkout=1"},{"label":"不可信代码（是否默认安全）","value":"#map:$s.unsafeCnt:0:是,*:否","level":"#map:$s.unsafeCnt:0:success,*:error"},{"key":"ctxSum","hidden":true,"value":"#sumlen:$findings.untrusted_context"},{"label":"不可信上下文变量（外部可控变量）","value":"#tpl:{s.ctxSum}","level":"#gt:$s.ctxSum:0:error"}],"failNote":"#tpl:评分：发现 {s.hits} 处危险模式 → score = {score}（二元判定，发现任意一处即 0 分，不按数量累加）","failEmptyText":"全部满足：已扫描的 workflow 文件均未发现危险模式","dataNote":"二元判定：发现任意危险模式即 0 分，未发现即 10 分。检测项：① allow-unsafe-pr-checkout: true；② 步骤中直接使用不可信上下文变量（atomgit.event.*）。","failItems":{"from":"$findings","filter":{"reason":"!=ok"},"card":{"title":"#tpl:危险命中：{path}","fields":[{"label":"workflow 文件","value":"$path"},{"label":"不可信代码（是否默认安全）","value":"#bool:$unsafe_checkout:否:是","level":"#bool:$unsafe_checkout:error:success"},{"label":"不可信上下文变量（外部可控变量）","value":"#join:$untrusted_context:、","level":"error"}],"reason":"#tpl:未满足：文件 {path} 命中危险模式（{reason}）","searchText":"#tpl:{path} {reason} {untrusted_context}"}},"groups":[{"key":"wf","label":"workflow 扫描明细","columns":[{"label":"workflow 文件","key":"path","type":"text"},{"label":"检查结果","key":"result","type":"text"},{"label":"不可信代码（是否默认安全）","key":"unsafe","type":"text"},{"label":"不可信上下文变量（外部可控变量）","key":"ctx","type":"text"}],"rowsFrom":"$findings","cellOf":{"path":{"text":"$path"},"result":{"text":"#map:$reason:ok:未发现危险模式,*:发现危险模式","level":"#map:$reason:ok:success,*:error"},"unsafe":{"text":"#bool:$unsafe_checkout:否:是","level":"#bool:$unsafe_checkout:error:success"},"ctx":{"text":"#join:$untrusted_context:、"}},"searchText":"#tpl:{path} {reason} {untrusted_context}"}]}',
1, 'ai-assisted', NOW());

-- 04 TOKEN_PERM 令牌权限
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('TOKEN_PERM',
'{"rule":{"brief":"检查 CI 中引用的插件（action）实际获得的权限，是否超出该插件正常工作所需的基准权限。已收录的插件基准权限见下表，未收录在基准表中的插件按只读权限检查。","formula":"得分 = 10 − 违规插件数（最低 0 分；同一插件多处引用只记一次）","conditions":[{"label":"pytest-orch","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"openlibing-upload-reports","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"test-result-display","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"openlibing-metadata-collect","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"precision-test","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"api-scan","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"openlibing-pre-commit-action","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"upload-sarif-action","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"code-metrics-action","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"security-compilation-options-action","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"sca-pr-scan","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"malicious-code-pr-scan","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"vulnerability-hunting-action","value":"project：none；pr：none；issue：none；note：none；repository：read"},{"label":"id-token","value":"id-token: write"}],"notes":["读写分离：job 下多个插件共享同一权限，全 job 开写会让所有只读基准插件同时违规"]},"definition":{"brief":"衡量 CI 中引用的插件（action）实际获得的权限是否超出其正常工作所需，即「CI 权限是否遵循最小权限原则」。","purpose":"job 下多个插件共享同一套权限，全 job 开写会让所有只读基准插件同时暴露；权限越大，凭据泄露或插件被投毒时的影响面越大。","details":[{"label":"数据来源","value":"workflow 文件中的插件引用与权限配置（per-action 基准表比对）"},{"label":"权限生效顺序","value":"job 级配置 > 文件顶层配置 > 平台默认（只读）"},{"label":"基准口径","value":"未收录在基准表中的插件按只读基准检查"}],"notes":["需要写权限的插件应单独拆 job 配置，避免一个 job 全量开写"]},"summary":[{"key":"files","label":"workflow 文件数","value":"$wf_file_count"},{"key":"checked","label":"受检插件数","value":"$stat.checked_count"},{"key":"viol","label":"违规插件数","value":"$stat.violation_count","level":"#gt:$stat.violation_count:0:error"}],"failNote":"#tpl:评分：10 − 1 × 违规插件数 {stat.violation_count} = {score}　｜　插件按基准表只需读权限，却在写权限上下文运行，每处扣 1 分","failEmptyText":"全部满足：所有受检插件均在所需权限内运行","dataNote":"v2 口径：检查 job 级 / 顶层 permissions 生效上下文中运行插件的实际所需权限（13 个官方插件基准表，名单外插件按只读兜底），每处违规扣 1 分；无 workflow 文件或未引用任何受检插件时为满分 10 分。","failItems":{"from":"$viol_rows","card":{"title":"#tpl:插件权限违规：{plugin}","fields":[{"label":"workflow 文件","value":"$path"},{"label":"job","value":"$job"},{"label":"插件","value":"$plugin","level":"error"}],"reason":"#tpl:插件 {plugin} 按基准表只需读权限，但 job {job} 以写权限上下文运行","searchText":"#tpl:{path} {job} {plugin}"}},"groups":[{"key":"viol","label":"违规插件明细","columns":[{"label":"workflow 文件","key":"path","type":"text"},{"label":"job","key":"job","type":"text"},{"label":"插件","key":"plugin","type":"text"}],"rowsFrom":"$viol_rows","cellOf":{"path":{"text":"$path"},"job":{"text":"$job"},"plugin":{"text":"$plugin","level":"error"}},"searchText":"#tpl:{path} {job} {plugin}"},{"key":"jobs","label":"job 权限明细","columns":[{"label":"workflow 文件","key":"path","type":"text"},{"label":"job","key":"job","type":"text"},{"label":"权限来源","key":"source","type":"text"},{"label":"生效 permissions","key":"perm","type":"text"},{"label":"是否含写权限","key":"write","type":"text"},{"label":"违规插件","key":"viol","type":"text"}],"rowsFrom":"$job_rows","cellOf":{"path":{"text":"$path"},"job":{"text":"$job"},"source":{"text":"#map:$perm_source:top:顶层继承,job:job 级声明,default:默认只读,no_job:无 job 定义"},"perm":{"text":"$perm"},"write":{"text":"#bool:$has_write:含写权限:只读","level":"#bool:$has_write:error:success"},"viol":{"text":"#join:$violations:，"}},"searchText":"#tpl:{path} {job}"}]}',
1, 'ai-assisted', NOW());

-- 05 PINNED_DEP 依赖锁定（gcheck 严格口径，2026-10-10 配置就绪，参照原型 20 号页）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('PINNED_DEP',
'{"rule":{"brief":"检查项目在构建和发布过程中使用的所有依赖应固定到具体的哈希值而非可变版本标签，确保构建的可重复性和依赖的安全性。","formula":"得分 = 已固定依赖数 / 依赖总数 × 10","conditions":[{"label":"容器镜像","value":"Dockerfile 的 FROM 与 workflow 的 container.image 须带 @sha256:<64 位摘要>；浮动 tag（如 ubuntu:22.04、latest）判不符合。FROM x AS y 构建阶段别名、${VAR} 变量引用无法静态判定，计入不符合但无需整改。"},{"label":"下载即执行","value":"远程脚本须由 URL 自带 40 位提交 SHA 固定（如 raw.githubusercontent.com/<owner>/<repo>/<40hex>/install.sh）；wget/curl 后直接执行、或仅用 sha256sum -c 校验，均判不符合。"},{"label":"Go 命令","value":"go install / go get 须指定完整语义化版本（如 @v1.2.3）或哈希；省略版本、@latest、分支引用判不符合。"},{"label":"pip 命令","value":"pip install 须带 --require-hashes，且需求文件每行带 --hash=；仅固定版本号、-r 未在命令行声明 --require-hashes 判不符合；本地路径安装（-e .）加 --no-deps 视为符合。"},{"label":"npm 命令","value":"须使用 npm ci 或把 git 依赖固定到哈希；npm install / npm i（即使仓库有 package-lock.json）判不符合。"},{"label":"Chocolatey","value":"choco install 须指定校验和；未要求校验和判不符合。"},{"label":"NuGet / .NET","value":"NuGet / dotnet restore 须启用锁定模式（lock 文件 / --locked-mode）；未启用判不符合。"}],"naCondition":"未识别到任何依赖（not-applicable）、无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA。","notes":[]},"definition":{"brief":"衡量构建与 CI 流程中引用的外部依赖是否固定到不可变版本（哈希 / 摘要），即「供应链依赖是否可复现、防篡改」。","purpose":"浮动版本的依赖可被上游篡改或消失，导致构建不可重现；固定到 sha256 摘要等不可变引用可保证供应链完整性与构建可重现性。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"检查范围","value":"容器镜像、pip/npm/go/choco/nuget 命令、下载即执行等 7 项判据"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 pinned-dependencies"}],"notes":[]},"summary":[{"key":"unpinned","hidden":true,"value":"#sub:$total_count,$pinned_count"},{"key":"rate","hidden":true,"value":"#pct:$pinned_count,$total_count"},{"label":"总依赖数","value":"$total_count"},{"label":"已固定","value":"$pinned_count","level":"#eq:$pinned_count:$total_count:success"},{"label":"未固定","value":"#tpl:{s.unpinned}","level":"#gt:$s.unpinned:0:error"},{"label":"合规率","value":"#tpl:{s.rate}%","level":"#lt:$pinned_count:$total_count:warning"}],"failNote":"#tpl:评分：已固定 {pinned_count} / 总依赖数 {total_count} × 10 = {score}　｜　严格口径：镜像须 @sha256 摘要、pip 须 --require-hashes，仅固定版本号不算固定","failEmptyText":"全部满足：全部依赖均已按严格口径固定（镜像 @sha256 / pip --require-hashes 等）","dataNote":"分子分母 = gcheck summary 的 compliant + nonCompliant（无法判定的条目不进分子分母）。判据默认 7 项（ciAction 关闭；downloadThenRun 上游不采集「已固定」的下载条目，命中即存在不合规下载）。完整依赖明细清单（全量、不截断）走独立分页接口，本页判据汇总按主表数据统计。整改指引为空或判定依据标注口径限制（变量引用 / 裸名引用等）的条目无需整改。","failItems":{"from":"$deps","filter":{"pinned":"=false"},"card":{"title":"#tpl:未固定依赖：{file}","fields":[{"label":"依赖类型","value":"#map:$type:containerImage:容器镜像,downloadThenRun:下载即执行,goCommand:Go 命令,pipCommand:pip 命令,npmCommand:npm 命令,chocoCommand:Chocolatey,nugetCommand:NuGet/.NET,ciAction:Action 引用,unknown:未识别,*:其他"},{"label":"文件","value":"$file"},{"label":"行号","value":"#ifnull:$line:—"},{"label":"依赖引用","value":"#ifnull:$ref:—"}],"reason":"#tpl:未满足：{file} 中的依赖未按严格口径固定（{reason}）","searchText":"#tpl:{file} {type} {ref}"}},"groups":[{"key":"judge","label":"判据汇总","columns":[{"label":"判据","key":"name","type":"text"},{"label":"命中","key":"hit","type":"number"},{"label":"符合","key":"ok","type":"number"},{"label":"不符合","key":"bad","type":"number"},{"label":"合规率","key":"rate","type":"text"}],"rows":[{"name":"容器镜像","hit":"#qcount:$deps:type=containerImage","ok":"#qcount:$deps:type=containerImage,pinned=true","bad":"#qcount:$deps:type=containerImage,pinned=false"},{"name":"下载即执行","hit":"#qcount:$deps:type=downloadThenRun","ok":"#qcount:$deps:type=downloadThenRun,pinned=true","bad":"#qcount:$deps:type=downloadThenRun,pinned=false"},{"name":"Go 命令","hit":"#qcount:$deps:type=goCommand","ok":"#qcount:$deps:type=goCommand,pinned=true","bad":"#qcount:$deps:type=goCommand,pinned=false"},{"name":"pip 命令","hit":"#qcount:$deps:type=pipCommand","ok":"#qcount:$deps:type=pipCommand,pinned=true","bad":"#qcount:$deps:type=pipCommand,pinned=false"},{"name":"npm 命令","hit":"#qcount:$deps:type=npmCommand","ok":"#qcount:$deps:type=npmCommand,pinned=true","bad":"#qcount:$deps:type=npmCommand,pinned=false"},{"name":"Chocolatey","hit":"#qcount:$deps:type=chocoCommand","ok":"#qcount:$deps:type=chocoCommand,pinned=true","bad":"#qcount:$deps:type=chocoCommand,pinned=false"},{"name":"NuGet / .NET","hit":"#qcount:$deps:type=nugetCommand","ok":"#qcount:$deps:type=nugetCommand,pinned=true","bad":"#qcount:$deps:type=nugetCommand,pinned=false"}],"cellOf":{"name":{"text":"$name"},"hit":{"text":"$hit"},"ok":{"text":"$ok","level":"#gt:$ok:0:success"},"bad":{"text":"$bad","level":"#gt:$bad:0:error"},"rate":{"text":"#pct:$ok,$hit,%"}},"searchText":"#tpl:{name} {hit} {ok} {bad}"}],"emptyHint":"本仓库未识别到任何依赖（NA），或 gcheck 无法运行，无明细数据"}',
1, 'ai-assisted', NOW());

-- 06 BINARY_ARTIFACTS 二进制制品（2026-10-09 口径切换：文件内容魔数识别，历史后缀清单口径作废）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('BINARY_ARTIFACTS',
'{"rule":{"brief":"检查仓库中是否直接提交了二进制可执行产物（检查文件头部若干字节，识别是否为二进制文件）","formula":"得分 = 10 − 二进制文件数（最低 0 分，每个文件扣 1 分）","conditions":[{"label":"二进制文件","value":"判断仓库内所有文件是否为二进制文件，命中即扣分"}],"notes":[]},"definition":{"brief":"检查仓库中是否直接提交了二进制可执行产物（检查文件头部若干字节，识别是否为二进制文件）。","purpose":"二进制产物无法进行代码评审、无法追踪来源与许可，是仓库投毒与许可污染的高风险载体。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"识别对象","value":"ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制（文件内容魔数识别）"},{"label":"参考标准","value":"OSSF Scorecard binary-artifacts"}],"notes":[]},"params":{"unit":"1"},"summary":[{"key":"n","label":"二进制文件数","value":"$binary_count","level":"#gt:$binary_count:0:error"},{"label":"每个扣分","value":"#tpl:{p.unit}"},{"key":"total","hidden":true,"value":"#mul:$binary_count,$p.unit"},{"label":"合计扣分","value":"#tpl:-{s.total}","level":"#gt:$binary_count:0:error"},{"label":"得分公式","value":"max(0, 10 − n)"}],"failNote":"#tpl:评分：max(0, 10 − 二进制文件数 {binary_count}) = {score}　｜　逐文件累加扣分（每个 {p.unit} 分）","failEmptyText":"全部满足：按文件内容魔数识别，全仓未检出二进制可执行产物，无扣分","dataNote":"扫描全仓文件树，按文件内容魔数识别真二进制可执行产物：ELF（Linux 可执行 / 共享库）、PE（Windows exe / dll）、Mach-O（macOS 可执行）、WASM（WebAssembly 模块）、ar 归档（.a 静态库）。文件名后缀不再作为判定依据：.gz / .zip / .pdf / .jar / .pyc 等非可执行产物不上报。自动排除 .git、testdata 等目录；vendor / node_modules 目录照报（上游口径）。文件路径从仓库根目录展示（前缀 /），点击经默认分支（blob/{branch}）跳转 GitCode 文件页。本指标没有 NA 条件。","failItems":{"from":"$artifact_types","card":{"title":"#tpl:检出二进制文件：/{path}","fields":[{"label":"文件路径","value":"#tpl:/{path}","href":"#tpl:https://gitcode.com/{repoPath}/blob/{branch}/{path}"},{"label":"产物类型","value":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},{"label":"扣分","value":"#tpl:-{p.unit}","level":"error"}],"reason":"#tpl:未满足：文件 /{path} 内容命中二进制魔数特征（{signal}）","searchText":"$path"}},"groups":[{"key":"bin","label":"二进制文件清单","columns":[{"label":"文件路径","key":"path","type":"text"},{"label":"产物类型","key":"type","type":"text"},{"label":"扣分","key":"ded","type":"number"}],"rowsFrom":"$artifact_types","cellOf":{"path":{"text":"#tpl:/{path}","href":"#tpl:https://gitcode.com/{repoPath}/blob/{branch}/{path}"},"type":{"text":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},"ded":{"text":"#tpl:-{p.unit}","level":"error"}},"searchText":"$path"}]}',
1, 'ai-assisted', NOW());

-- 07 CODE_REVIEW 代码评审（2026-10-10 新增"全部扫描 PR"分组：借用 pr_ci_detail 全量明细，无 CI 列）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CODE_REVIEW',
'{"rule":{"brief":"检查最近 30 次已合入 PR 中，每个 PR 是否存在有效评审：存在非机器人、非创建人的 /lgtm 评论。","formula":"得分 = 已评审 PR 数 / PR 总数 × 10","conditions":[{"label":"已评审","value":"存在非机器人、非创建人的 /lgtm 评论"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"剔除机器人创建的 PR 后数量为 0 时，本指标不参评。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否经过有效人工评审：存在非机器人、非创建人给出的 /lgtm 认可。","purpose":"人工评审是代码质量与安全的最后一道人肉防线，未经评审的代码合入会放大缺陷与后门风险。","details":[{"label":"数据来源","value":"PR 评论扫描（/lgtm 命令）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"},{"label":"参考标准","value":"对齐 OSSF Scorecard code-review 思想"}],"notes":[]},"summary":[{"key":"total","label":"纳入统计 PR","value":"$pr_total_count"},{"key":"reviewed","label":"已评审","value":"$pr_reviewed_count","level":"#gt:$pr_reviewed_count:0:success"},{"key":"unreviewed","label":"未评审","value":"#sub:$pr_total_count,$pr_reviewed_count","level":"#lt:$pr_reviewed_count:$pr_total_count:error"},{"key":"rate","hidden":true,"value":"#pct:$pr_reviewed_count,$pr_total_count"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"}],"failNote":"#tpl:评分：已评审 {pr_reviewed_count} / 纳入统计 {pr_total_count} × 10 = {score}　｜　每条未评审 PR 扣 10 / {pr_total_count}，合计扣 {s.deduct}　｜　评审率 {s.rate}%","failEmptyText":"全部满足：近 30 次已合入 PR 均已完成有效评审，无扣分","dataNote":"统计近 30 次已合入 PR（剔除机器人创建后纳入统计）。","failItems":{"from":"$pr_unreviewed_detail","card":{"title":"#tpl:PR #{number} 未通过评审","fields":[{"label":"PR","value":"#tpl:#{number}","href":"$url"},{"label":"标题","value":"#ifnull:$title:—"},{"label":"创建人","value":"#ifnull:$creator:—"},{"label":"合入时间","value":"$merged_at"},{"label":"评审结果","value":"未评审","level":"error"}],"reason":"#tpl:未满足：PR #{number} 已合入（{merged_at}）但未经过有效评审","searchText":"#tpl:{number} {title} {creator} 未评审 {merged_at}"}},"groups":[{"key":"pr","label":"未评审 PR 明细","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"合入时间","key":"merged","type":"text"},{"label":"评审结果","key":"result","type":"text"}],"rowsFrom":"$pr_unreviewed_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"},"merged":{"text":"$merged_at"},"result":{"text":"未评审","level":"error"}},"rowLevel":"error","searchText":"#tpl:{number} {title} {creator} {merged_at} 未评审"},{"key":"pr_all","label":"全部扫描 PR","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"}],"rowsFrom":"$pr_ci_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"}},"searchText":"#tpl:{number} {title} {creator}"}]}',
1, 'ai-assisted', NOW());

-- 08 BRANCH_PROTECTION 分支保护（v2 已激活，明细取 dwi_rd_efc_security_branch_protect_scan；2026-10-14 展示口径改为 5 层递进 B1-B5；2026-10-15 修订：规则明列 5 层、去「双人 LGTM」术语、精简不满足区文案；二次修订：概览隐藏「未评估层级」，「增强管控」改为「评审人数要求（默认 1，配置取实际值）」）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('BRANCH_PROTECTION',
'{"rule":{"brief":"检查仓库默认分支的保护规则是否到位，具体检查内容见下表。","formula":"总分 10 分 ，递进式计分，如下表。","conditions":[{"label":"第 1 层（3 分）","value":"禁止删除分支、禁止强制推送"},{"label":"第 2 层（3 分）","value":"要求 1 名以上审查者、要求通过 PR 合并、要求分支保持最新、要求最近推送审批"},{"label":"第 3 层（2 分）","value":"要求 CI 状态检查通过"},{"label":"第 4 层（1 分）","value":"要求 2 名以上审查者、要求 CODEOWNERS 审查"},{"label":"第 5 层（1 分）","value":"取消过时审查、管理员强制执行保护规则"}],"notes":[]},"definition":{"brief":"衡量仓库受保护分支的管控强度：指标定义 5 层递进——禁止删除/强推、基础评审要求、CI 门禁、双人审查、取消过时审查/管理员强制执行；GitCode 平台默认管控覆盖前 3 层，后 2 层考察 rebot.yaml 2 名及以上审查者配置与落实。","purpose":"分支保护防止绕过评审直接 push；多人审批保证关键代码至少经两人把关，降低单点失误与恶意合入的风险。","details":[{"label":"数据来源","value":"GitCode 平台默认分支保护（平台级）+ .infra_self_service/rebot.yaml 配置扫描 + 近 30 个已合入 PR 的 /lgtm 评论"},{"label":"统计口径","value":"近 30 个已合入 PR 的 /lgtm 评论（剔除机器人和 PR 作者）"},{"label":"评分结构","value":"5 层递进 3+3+2+1+1：第 1-3 层映射平台默认基线 8 分，第 4-5 层映射 rebot.yaml 2 名及以上审查者增强 2 分"}],"notes":[]},"summary":[{"key":"tiers","label":"已满足层级","value":"#map:$pr_lgtm_pass:1:5 / 5,*:3 / 5","level":"#map:$pr_lgtm_pass:1:success,*:"},{"key":"need","label":"评审人数要求","value":"#ifnull:$lgtm_need_num:1","level":"#map:$has_rebot_yaml:1:success,0:na,*:"},{"key":"prpass","label":"审查者人数检查","value":"#map:$pr_lgtm_pass:1:全部达标,0:存在未达标,*:未执行","level":"#map:$pr_lgtm_pass:1:success,0:error,*:na"}],"failNote":"#tpl:第 1-3 层平台默认满足（基线 8 分）；第 4 层未满足，第 5 层不再判定。当前得分 {score} 分","failEmptyText":"满分 10 分：5 层全部满足；第 4-5 层 rebot.yaml 配置 lgtm_need_num=2 且近 30 个已合入 PR 均有 2 名及以上审查者认可","dataNote":"指标定义采用 5 层递进计分（上一层全部满足才进入下一层），结合平台实际映射：第 1-3 层由 GitCode 平台默认分支保护满足（基线 8 分）；第 4-5 层考察 .infra_self_service/rebot.yaml 2 名及以上审查者配置与落实（+2 分），第 5 层与第 4 层同判——第 4 层不满足时第 5 层显示「未评估」。达标口径：近 30 个已合入 PR 每个都有 2 名及以上不同审查者（剔除机器人与 PR 作者）的 /lgtm。数据来源：P1 扫描 rebot.yaml + /lgtm 评论。","emptyHint":"该仓库暂无分支保护扫描数据","failItems":[{"when":"has_rebot_yaml=0","title":"第 4 层未满足：未启用 2 名及以上审查者","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"未配置","level":"error"},{"label":"第 5 层","value":"未评估","level":"na"},{"label":"提升建议","value":"配置 .infra_self_service/rebot.yaml 并设置 lgtm_need_num=2"}],"reason":"未检出 .infra_self_service/rebot.yaml，第 4 层不满足，第 5 层不再判定 → 得分 3+3+2 = 8","searchText":"rebot.yaml 未配置 2名及以上审查者 第4层 未评估"},{"when":"has_rebot_yaml=1 && lgtm_need_num!=2","title":"第 4 层未满足：审查者人数要求未配置为 2 人","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"已配置","level":"success"},{"label":"审查者人数要求","value":"#ifnull:$lgtm_need_num:—","level":"error"},{"label":"第 5 层","value":"未评估","level":"na"},{"label":"提升建议","value":"将 rebot.yaml 的 lgtm_need_num 设置为 2"}],"reason":"已配置 rebot.yaml 但 lgtm_need_num≠2，不触发 2 名及以上审查者检查，第 5 层不再判定 → 得分 8","searchText":"lgtm_need_num 审查者人数要求 第4层 未评估"},{"when":"pr_lgtm_pass=0","title":"第 4 层未满足：存在审查者未达标的已合入 PR","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"已配置（lgtm_need_num=2）","level":"success"},{"label":"PR 审查达标","value":"存在未达标","level":"error"},{"label":"达标要求","value":"每个已合入 PR 有 2 名及以上审查者（剔机器人/作者）认可"},{"label":"第 5 层","value":"未评估","level":"na"}],"reason":"已配置 2 名及以上审查者，但近 30 个已合入 PR 中存在未达标 PR，第 5 层不再判定 → 得分 8","searchText":"审查者未达标 PR 第4层 未评估"}],"groups":[{"key":"tier","label":"层级递进判定","columns":[{"label":"层级","key":"lvl","type":"text"},{"label":"检查项","key":"items","type":"text"},{"label":"层级分值","key":"pts","type":"number"},{"label":"判定结果","key":"res","type":"text"},{"label":"判定依据","key":"basis","type":"text"}],"rows":[{"lvl":"第 1 层","items":"禁止删除分支、禁止强制推送","pts":"3","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 2 层","items":"要求 1 名以上审查者、要求通过 PR 合并、要求分支保持最新、要求最近推送审批","pts":"3","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 3 层","items":"要求 CI 状态检查通过","pts":"2","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 4 层","items":"要求 2 名以上审查者、要求 CODEOWNERS 审查","pts":"1","res":"#map:$pr_lgtm_pass:1:满足,*:不满足","basis":"#map:$pr_lgtm_pass:1:rebot.yaml 配置 lgtm_need_num=2，近 30 个已合入 PR 全部达标,*:未启用 2 名及以上审查者（未配置 rebot.yaml 或 lgtm_need_num≠2）"},{"lvl":"第 5 层","items":"取消过时审查、管理员强制执行保护规则","pts":"1","res":"#map:$pr_lgtm_pass:1:满足,*:未评估","basis":"#map:$pr_lgtm_pass:1:与第 4 层同判：2 名及以上审查者落实即视为满足,*:层级递进：第 4 层未满足，本层不再判定"}],"rowLevel":"#map:$res:不满足:error","cellOf":{"lvl":{"text":"$lvl"},"items":{"text":"$items"},"pts":{"text":"$pts"},"res":{"text":"$res","level":"#map:$res:满足:success,不满足:error,未评估:na"},"basis":{"text":"$basis"}},"searchText":"#tpl:{lvl} {items} {res} {basis}"},{"key":"prs","label":"近 30 PR lgtm 审批明细","columns":[{"label":"PR 号","key":"num","type":"number"},{"label":"lgtm 数","key":"cnt","type":"number"},{"label":"评审人数","key":"distinct","type":"number"},{"label":"是否达标","key":"pass","type":"text"},{"label":"审批人","key":"authors","type":"text"}],"rowsFrom":"$pr_lgtm_detail","cellOf":{"num":{"text":"#tpl:#{pr_number}","href":"#href:https://gitcode.com/{repoPath}/merge_requests/{pr_number}"},"cnt":{"text":"$lgtm_count"},"distinct":{"text":"$distinct_author"},"pass":{"text":"#bool:$pass:达标:未达标","level":"#bool:$pass:success:error"},"authors":{"text":"#join:$lgtms:login:、"}},"searchText":"#tpl:{pr_number} {lgtm_count}"}]}',
1, 'ai-assisted', NOW());

-- 09 WEBHOOKS 钩子密钥（活跃钩子需配置 secret）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('WEBHOOKS',
'{"rule":{"brief":"检查仓库活跃的 Webhook 中，是否配置密钥（secret）。未配密钥的 Webhook 请求可被伪造。","formula":"得分 = 10 × 配置密钥的 Webhook 数 / 活跃 Webhook 总数（向下取整）","conditions":[{"label":"已配密钥","value":"活跃（active）且密钥非空"},{"label":"无活跃钩子","value":"10 分"}],"notes":[]},"definition":{"brief":"衡量仓库活跃 Webhook 中已配置密钥（secret）的比例：密钥缺失的接收端可被任何人伪造请求触发。","purpose":"未配密钥的 Webhook 请求无法验证来源，攻击者可伪造事件触发内部流程，导致敏感信息泄露或非授权操作。","details":[{"label":"数据来源","value":"平台 API 采集的 Webhook 配置"},{"label":"统计口径","value":"分母只计活跃（active=1）钩子，未激活与状态未知的不计入"},{"label":"判定","value":"已配置密钥 = password_is_null=0（采集层不落密码明文）"}],"notes":[]},"summary":[{"key":"all","label":"Webhook 总数","value":"#count:$webhooks"},{"key":"act","hidden":true,"value":"#ifnull:$active_count:0"},{"key":"secured","label":"活跃中已配密钥","value":"#ifnull:$secured_count:0","level":"#gt:$s.secured:0:success"},{"key":"unsecured","label":"活跃中未配密钥","value":"#sub:$active_count,$secured_count","level":"#gt:$s.unsecured:0:error"},{"label":"未激活（不计入）","value":"#sub:#count:$webhooks,$active_count","level":"na"}],"failNote":"#tpl:评分：⌊10 × 已配置密钥 {secured_count} / 活跃钩子 {active_count}⌋ = {score}　｜　每条未配置密钥的活跃钩子扣分　｜　⌊ ⌋ 为向下取整","failEmptyText":"全部满足：活跃 Webhook 均已配置密钥","dataNote":"分母只计 active=1 的活跃钩子；未激活与状态未知的钩子均不计入分母。已配置密钥判定 = active=1 且 password_is_null=0。采集层不落密码明文，只落 password_is_null 布尔位。Webhook 创建时间暂未采集，明细列已降级。","failItems":{"from":"$webhooks","filter":{"active":"=1","password_is_null":"=1"},"card":{"title":"#tpl:Webhook #{id} 未配置密钥","fields":[{"label":"#","value":"#tpl:{id}"},{"label":"URL","value":"$url"},{"label":"活跃状态","value":"活跃"},{"label":"密钥配置","value":"未配置","level":"error"}],"reason":"#tpl:未满足：活跃 Webhook #{id}（{url}）未配置密钥","searchText":"#tpl:{id} {url}"}},"groups":[{"key":"wh","label":"Webhook 清单","columns":[{"label":"id","key":"id","type":"number"},{"label":"Webhook URL","key":"url","type":"text"},{"label":"活跃状态","key":"active","type":"text"},{"label":"密钥配置","key":"secret","type":"text"}],"rowsFrom":"$webhooks","cellOf":{"id":{"text":"#tpl:{id}"},"url":{"text":"$url"},"active":{"text":"#bool:$active:活跃:未激活","level":"#bool:$active::na"},"secret":{"text":"#bool:$password_is_null:未配置:已配置","level":"#bool:$password_is_null:error:success"}},"searchText":"#tpl:{id} {url}"}]}',
1, 'ai-assisted', NOW());

-- 10 CI_TESTS CI 测试（最近 30 次已合入 PR 是否跑 CI）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CI_TESTS',
'{"rule":{"brief":"检查最近 30 次已合入 PR 中，每个 PR 是否有 CI 流水线测试任务执行记录。","formula":"得分 = 10 × 有 CI 的 PR 数 / PR 总数","conditions":[{"label":"测试任务","value":"PR关联到流水线测试任务执行记录"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"仓库无已合入 PR 时，本指标不参评。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否有 CI 流水线测试任务执行记录：代码合入前是否经过自动化构建与测试把关。","purpose":"无 CI 把关的 PR 缺陷可直接进入主干，回归风险不可控；CI 覆盖率反映工程化质量水位。","details":[{"label":"数据来源","value":"PR 与流水线执行记录关联（CodeArts 关联表）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"notes":["PR 关联到流水线测试任务（job_type=DT）执行记录即视为有 CI，不考察任务结果成败"]},"summary":[{"key":"total","label":"纳入统计 PR","value":"$pr_total_count"},{"key":"ci","label":"已跑 CI","value":"#qcount:$pr_ci_detail:has_ci=1","level":"#gt:$s.ci:0:success"},{"key":"noci","label":"未跑 CI","value":"#qcount:$pr_ci_detail:has_ci=0","level":"#gt:$s.noci:0:error"},{"key":"rate","hidden":true,"value":"#pct:$s.ci,$pr_total_count"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"}],"failNote":"#tpl:评分：已跑 CI {s.ci} / 纳入统计 {pr_total_count} × 10 = {score}　｜　每条未跑 CI 的 PR 扣 10 / {pr_total_count}，合计扣 {s.deduct}　｜　CI 覆盖率 {s.rate}%","failEmptyText":"全部满足：近 30 次已合入 PR 均关联到流水线测试任务执行记录，无扣分","dataNote":"统计近 30 次已合入 PR 的 CI 流水线测试任务执行记录。流水线链接明细暂未采集。","failItems":{"from":"$pr_ci_detail","filter":{"has_ci":"=0"},"card":{"title":"#tpl:PR #{number} 未执行 CI 测试","fields":[{"label":"PR","value":"#tpl:#{number}","href":"$url"},{"label":"标题","value":"#ifnull:$title:—"},{"label":"创建人","value":"#ifnull:$creator:—"},{"label":"是否执行CI测试","value":"否","level":"error"}],"reason":"#tpl:未满足：PR #{number} 已合入但未执行CI测试","searchText":"#tpl:{number} {title} {creator} 未执行CI测试"}},"groups":[{"key":"pr","label":"PR CI 明细","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"是否执行CI测试","key":"ci","type":"text"}],"rowsFrom":"$pr_ci_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"},"ci":{"text":"#bool:$has_ci:是:否","level":"#bool:$has_ci:success:error"}},"searchText":"#tpl:{number} {title} {creator}"}]}',
1, 'ai-assisted', NOW());

-- 11 SIGNED_RELEASES 签名发布（release 含 GPG 签名）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SIGNED_RELEASES',
'{"rule":{"brief":"检查最近 30 个正式 Release 版本的附件中，是否包含数字签名文件或 sha256 文件。","formula":"全部版本均有签名 = 10 分；任一版本缺少签名 = 0 分（一票否决）","conditions":[{"label":"签名文件","value":".asc / .sig / .pgp / .gpg / .minisig / .pem / .crt / .cer / .p7s"},{"label":"sha256 文件","value":".sha256 / .sha256sum 资产"}],"naCondition":"仓库没有任何 Release 时，本指标不参评。","notes":[]},"definition":{"brief":"衡量最近 30 个正式版本是否包含数字签名与 sha256 校验文件：发布物能否被验证完整性与来源。","purpose":"版本签名让使用者可验证下载内容未被篡改、确实来自官方构建，防止被投毒的发行包流入下游。","details":[{"label":"数据来源","value":"平台 Release 资产扫描"},{"label":"统计口径","value":"最近 30 个正式版本；仅有源码包（source only）的版本已直接排除、不进入评估范围"},{"label":"判定","value":"数字签名资产（.asc/.sig/.pgp 等）与 sha256 校验文件（.sha256/.sha256sum）均须存在"}],"notes":[]},"summary":[{"label":"评估版本数","value":"$release_count"},{"label":"含签名","value":"$signed_count","level":"#gt:$signed_count:0:success"},{"key":"unsigned","label":"不含签名","value":"#sub:$release_count,$signed_count","level":"#gt:$s.unsigned:0:error"}],"failNote":"#tpl:评分：全部版本均含签名才得 10 分，本仓库有 {s.unsigned} 个版本不满足　→　score = {score}（二元判定，非按比例扣分；故卡片不显示逐条扣分）","failEmptyText":"全部满足：最近 30 个正式版本均含数字签名文件与 sha256 文件","dataNote":"评估范围为最近 30 个正式版本，仅有源码包（source only）的版本已直接排除、不进入评估范围。签名判定 = 数字签名资产（.asc/.sig/.pgp 等）与 sha256 校验文件（.sha256/.sha256sum）均须存在。发布时间与资产数暂未采集，明细列已降级。","failItems":{"from":"$releases","filter":{"has_signature":"=0"},"card":{"title":"#tpl:版本 {tag} 不含签名","fields":[{"label":"版本","value":"$tag"},{"label":"数字签名","value":"不含签名","level":"error"}],"reason":"#tpl:未满足：版本 {tag} 未检出数字签名文件或 sha256 文件","searchText":"$tag"}},"groups":[{"key":"rel","label":"版本清单","columns":[{"label":"版本","key":"tag","type":"text"},{"label":"数字签名","key":"sig","type":"text"}],"rowsFrom":"$releases","cellOf":{"tag":{"text":"$tag"},"sig":{"text":"#bool:$has_signature:已签名:未签名","level":"#bool:$has_signature:success:error"}},"searchText":"$tag"}]}',
1, 'ai-assisted', NOW());

-- 12 PACKAGING 软件包发布（euler 包名匹配 + obs-upload/upload-artifact workflow 插件，2026-10-06 口径修正）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('PACKAGING',
'{"rule":{"brief":"检查仓库是否具备自动化打包发布能力：workflow 中配置了制品上传插件（obs-upload 或 upload-artifact）；或仓库被收录在 openEuler（Eluermaker）打包工程清单中。","formula":"具备自动化打包发布能力 = 10 分；未检出 = 0 分（视为未建立自动发包流程）","conditions":[{"label":"判定条件","value":"workflow 中使用制品上传插件（obs-upload / upload-artifact），或仓库命中 openEuler 打包工程清单"}],"notes":[]},"definition":{"brief":"衡量仓库是否具备自动化发包流程：workflow 中配置了制品上传插件，或被 openEuler 打包工程收录。","purpose":"自动化发包保证发布过程可重复、可审计，减少人工操作引入的错漏与安全风险。","details":[{"label":"数据来源","value":"workflow 文件扫描 + openEuler 打包工程清单比对（包名口径）"},{"label":"判定条件","value":"workflow 中使用 obs-upload / upload-artifact 制品上传插件，或仓库命中 openEuler 包清单"}],"notes":["openEuler 社区存在独立发包流程，命中其包清单同样视为满足"]},"summary":[{"key":"sat","hidden":true,"value":"#sat:$has_publish_plugin,$in_openeuler_project"},{"label":"自动化发包能力","value":"#map:$s.sat:0:不满足,*:满足","level":"#map:$s.sat:0:error,*:success"}],"failNote":"#tpl:评分：检测到自动化打包发布能力（制品上传插件或 openEuler 包清单命中，满足任一）= 10 分，未检测到 = 0 分 → score = {score}","failEmptyText":"全部满足：已检测到自动化打包发布能力（制品上传插件或 openEuler 构建命中），计 10 分","dataNote":"当前检查项：自动化打包发布能力 —— ① 核心 workflow 中是否存在制品上传插件（obs-upload、upload-artifact 两种）；② openEuler 社区存在独立发包流程，仓库名命中 openEuler 包清单同样视为满足。","failItems":[{"when":"has_publish_plugin=0 && in_openeuler_project=0","title":"未检测到自动化打包发布能力","fields":[{"label":"检查项","value":"自动化打包发布"},{"label":"检查范围","value":"workflow 制品上传插件（obs-upload、upload-artifact）+ openEuler 包清单"},{"label":"检查结果","value":"未检出","level":"error"}],"reason":"未满足：workflow 中未检出制品上传插件（obs-upload / upload-artifact），且未命中 openEuler 包清单，视为未建立自动发包流程","searchText":"未检测到自动化打包发布 packaging"}],"groups":[{"key":"chk","label":"当前检查项","columns":[{"label":"检查项","key":"item","type":"text"},{"label":"检查范围","key":"scope","type":"text"},{"label":"判定条件","key":"rule","type":"text"}],"rows":[{"item":"自动化打包发布","scope":".gitcode/workflows 目录 + openEuler 包清单","rule":"workflow 中使用 obs-upload / upload-artifact 制品上传插件，或仓库命中 openEuler 包清单"}],"cellOf":{"item":{"text":"$item"},"scope":{"text":"$scope"},"rule":{"text":"$rule"}},"searchText":"#tpl:{item} {scope}"},{"key":"pk","label":"插件命中明细","columns":[{"label":"workflow 文件","key":"wf","type":"text"},{"label":"命中插件","key":"uses","type":"text"}],"rowsFrom":"$publish_plugins","cellOf":{"wf":{"text":"$workflow"},"uses":{"text":"$uses","level":"success"}},"searchText":"$workflow"}],"emptyHint":"未检出自动化打包发布能力（制品上传插件与 openEuler 包清单均未命中）时，无插件命中明细"}',
1, 'ai-assisted', NOW());

-- 13 SAST 静态代码分析（pre-commit hook）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SAST',
'{"rule":{"brief":"检查pre-commit配置(根目录或pre-commit目录）或workflow文件中，是否使用了任一静态分析(SAST)工具,不区分语言。","formula":"命中任一工具 = 10 分（多个不加分）；有配置文件但 0 命中 = 0 分","conditions":[{"label":"工具清单","value":"clang-tidy / bandit / eslint / gosec / clippy / spotbugs / gitleaks / luacheck"}],"naCondition":"既没有 pre-commit 配置文件、又没有 workflow 文件时，本指标不参评。","notes":[]},"definition":{"brief":"衡量仓库是否在 pre-commit 配置或 workflow 中使用静态分析（SAST）工具，不区分语言。","purpose":"静态分析在编码阶段自动发现安全缺陷与代码坏味道，把安全问题左移到提交前，修复成本最低。","details":[{"label":"数据来源","value":"pre-commit 配置与 .gitcode/workflows 文件扫描"},{"label":"工具清单","value":"clang-tidy、bandit、eslint、gosec、clippy、spotbugs、gitleaks、luacheck（8 项）"},{"label":"判定","value":"任一命中即满分（二元判定，多命中不加分）"}],"notes":[]},"summary":[{"key":"toolCnt","hidden":true,"value":"$tool_count"},{"key":"hitJoined","hidden":true,"value":"#join:$hit_tools:、"},{"label":"检测结果","value":"#bool:$s.toolCnt:检出 SAST 工具:未检出","level":"#bool:$s.toolCnt:success:error"}],"failNote":"#tpl:评分：二元判定 → pre-commit / workflow 中共命中 {s.toolCnt} 个 SAST 工具 → score = {score}（任一命中即 10 分，多命中不加分）","failEmptyText":"#tpl:全部满足：共命中 {s.toolCnt} 个 SAST 工具：{s.hitJoined}","dataNote":"二元判定：pre-commit 配置（.pre-commit-config.yaml 或 pre-commit/.pre-commit-config.yaml）或 workflow 文件（.gitcode/workflows、.gitcode/workflow）中使用任一 SAST 工具即 10 分，有配置文件但均未使用即 0 分；两类文件都不存在记 NA（no_config_file）。工具清单（不区分语言）：clang-tidy、bandit、eslint、gosec、clippy、spotbugs、gitleaks、luacheck。pre-commit 按 hook id 匹配（兼容 id: xxx 与 id:xxx 写法），workflow 按单词边界匹配。","failItems":[{"when":"tool_count=0","title":"未检出任何 SAST 工具","fields":[{"label":"pre-commit 配置","value":"#join:$precommit_paths:、"},{"label":"workflow 文件数","value":"#tpl:{wf_file_count}"},{"label":"命中工具数","value":"#tpl:{tool_count} / 8","level":"error"},{"label":"判定","value":"pre-commit 与 workflow 中均未使用 SAST 工具","level":"error"}],"reason":"未满足：pre-commit 配置与 workflow 文件中均未检出 SAST 工具","searchText":"sast 未检出 pre-commit workflow 静态分析"}],"groups":[{"key":"tools","label":"SAST 工具检测明细（8 项）","columns":[{"label":"工具","key":"tool","type":"text"},{"label":"语言","key":"lang","type":"text"},{"label":"pre-commit","key":"pc","type":"text"},{"label":"workflow","key":"wf","type":"text"},{"label":"判定","key":"hit","type":"text"}],"rowsFrom":"$tools","cellOf":{"tool":{"text":"$tool"},"lang":{"text":"$lang"},"pc":{"text":"#bool:$precommit:命中:—","level":"#bool:$precommit:success:"},"wf":{"text":"#bool:$workflow:命中:—","level":"#bool:$workflow:success:"},"hit":{"text":"#bool:$hit:使用:未使用","level":"#bool:$hit:success:error"}},"searchText":"#tpl:{tool} {lang}"},{"key":"hits","label":"命中证据","columns":[{"label":"工具","key":"tool","type":"text"},{"label":"语言","key":"lang","type":"text"},{"label":"来源","key":"source","type":"text"},{"label":"文件","key":"path","type":"text"},{"label":"证据","key":"evidence","type":"text"}],"rowsFrom":"$hits","cellOf":{"tool":{"text":"$tool"},"lang":{"text":"$lang"},"source":{"text":"#map:$source:pre-commit:pre-commit 配置,workflow:workflow 文件,*:—"},"path":{"text":"$path"},"evidence":{"text":"$evidence"}},"searchText":"#tpl:{tool} {source} {path} {evidence}"}]}',
1, 'ai-assisted', NOW());

-- 14 FUZZING 模糊测试（gcheck 内置 Python 引擎，2026-10-10 接入）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('FUZZING',
'{"rule":{"brief":"检查仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目名单、通过 .clusterfuzzlite/Dockerfile 集成 ClusterFuzzLite、使用语言原生/内置 fuzz 能力（go test fuzz / libFuzzer / atheris / cargo-fuzz / Jazzer 等），或配置 property-testing。共 17 项判据（2 项非语言 + 7 项引擎型 + 8 项 Fuzz框架）。","formula":"阶梯计分，只取满足的最高档：OSS-Fuzz 或 ClusterFuzzLite = 10 分；语言原生/内置 fuzz = 5 分；property-testing = 3 分；全部未检出 = 0 分。","conditions":[{"label":"OSS-Fuzz","value":"仓库收录于 OSS-Fuzz 官方项目名单（main_repo 归一化比对）"},{"label":"ClusterFuzzLite","value":"检出精确路径 .clusterfuzzlite/Dockerfile（大小写敏感精确比对），且文件内容存在非空、非 # 注释的有效行"},{"label":"原生/内置 fuzz","value":"go test fuzz、C/C++/Swift libFuzzer、python-atheris、rust cargo-fuzz、java Jazzer"},{"label":"property-testing","value":"Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam 属性测试框架"}],"notes":[]},"definition":{"brief":"衡量仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目、配置 ClusterFuzzLite、使用语言原生 fuzz 能力，或配置属性测试（property-testing）。","purpose":"模糊测试能自动发现内存破坏、解析崩溃等深度漏洞，是解析器、加解密等高危代码的重要防线。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据），OSS-Fuzz 名单快照比对"},{"label":"判据构成","value":"2 项非语言判据 + 7 项引擎型判据 + 8 项属性测试判据，共 17 项"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 fuzzing + property-testing 阶梯扩展"}],"notes":[]},"summary":[{"key":"isNone","hidden":true,"value":"#map:$tier:none:1,*:0"},{"label":"检测结果","value":"#map:$tier:oss_fuzz:OSS-Fuzz（10分）,clusterfuzzlite:ClusterFuzzLite（10分）,native_fuzz:原生/内置 fuzz（5分）,property_testing:Fuzz框架（3分）,none:无任何 Fuzzing 活动（0分）","level":"#map:$tier:oss_fuzz:success,clusterfuzzlite:success,native_fuzz:success,property_testing:warning,none:error"}],"failNote":"#tpl:阶梯计分：只取满足的最高档，无逐条扣分（故卡片不显示扣分值）　｜　当前 {score} 分","failEmptyText":"满分：已集成 OSS-Fuzz 或配置 ClusterFuzzLite，取最高档 10 分","dataNote":"OSS-Fuzz 判定依据 OSS-Fuzz 官方项目名单快照（main_repo 归一化比对）。原生/内置 fuzz / property-testing 按代码特征识别（fuzz 函数 / 构建脚本 / 测试框架）。证据明细最多展示前 50 条。17 项判据全部未命中时产出仓库级未检出条目（无文件可派单），不单独铺卡。","failItems":[{"when":"isNone=1","title":"未检出任何模糊测试活动","fields":[{"label":"检测结果","value":"无任何 Fuzzing 活动（0 分）","level":"error"},{"label":"OSS-Fuzz 名单","value":"#bool:$in_ossfuzz:已收录:未收录"},{"label":"ClusterFuzzLite","value":"未配置"},{"label":"原生/内置 fuzz","value":"未检出"},{"label":"Fuzz框架","value":"未检出"}],"reason":"未满足：17 项判据全部未命中 —— 未检出 OSS-Fuzz 收录 / ClusterFuzzLite 配置 / 语言原生/内置 fuzz / property-testing 任何一类模糊测试活动","searchText":"fuzzing 未检出 模糊测试"}],"groups":[{"key":"ladder","label":"评分列表","columns":[{"label":"评分项","key":"name","type":"text"},{"label":"分数","key":"score","type":"number"},{"label":"是否使用","key":"used","type":"text"},{"label":"判定依据","key":"check","type":"text"}],"rows":[{"name":"集成 OSS-Fuzz","score":"10","used":"#map:$tier:oss_fuzz:是,*:否","check":"仓库身份与 OSS-Fuzz 名单每个项目的 main_repo 归一化成小写 host/org/repo 后比对"},{"name":"配置 ClusterFuzzLite","score":"10","used":"#map:$tier:clusterfuzzlite:是,*:否","check":"检出精确路径 .clusterfuzzlite/Dockerfile（大小写敏感精确比对），且文件内容存在非空、非 # 注释的有效行"},{"name":"原生/内置 fuzz","score":"5","used":"#map:$tier:native_fuzz:是,*:否","check":"7 项引擎型判据命中任一：Go testing.F / LibFuzzer（C·C++·Swift）/ Atheris / cargo-fuzz / Jazzer"},{"name":"Fuzz框架","score":"3","used":"#map:$tier:property_testing:是,*:否","check":"8 项 Fuzz框架判据命中任一：Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam"},{"name":"无任何 Fuzzing 活动","score":"0","used":"#map:$tier:none:是,*:否","check":"17 项判据全部未命中 —— 仓库级未检出条目（id=null、scope=repo）"}],"cellOf":{"name":{"text":"$name"},"score":{"text":"$score"},"used":{"text":"$used"},"check":{"text":"$check"}},"searchText":"#tpl:{name} {score} {check}"},{"key":"sig","label":"fuzz 集成证据","columns":[{"label":"判据","key":"crit","type":"text"},{"label":"文件","key":"file","type":"text"},{"label":"行号","key":"line","type":"text"},{"label":"代码片段","key":"snippet","type":"text"}],"rowsFrom":"$signals","cellOf":{"crit":{"text":"#map:$criterion:ossFuzz:OSS-Fuzz,clusterFuzzLite:ClusterFuzzLite,go-native:go test fuzz,c-libfuzzer:C libFuzzer,cpp-libfuzzer:C++ libFuzzer,swift-libfuzzer:Swift libFuzzer,python-atheris:Python atheris,rust-cargo-fuzz:Rust cargo-fuzz,java-jazzer:Java Jazzer,haskell-property-testing:Haskell 属性测试,javascript-property-testing:JavaScript 属性测试,typescript-property-testing:TypeScript 属性测试,csharp-property-testing:C# 属性测试,fsharp-property-testing:F# 属性测试,erlang-property-testing:Erlang 属性测试,elixir-property-testing:Elixir 属性测试,gleam-property-testing:Gleam 属性测试,*:其他"},"file":{"text":"$file"},"line":{"text":"#ifnull:$line:—"},"snippet":{"text":"#ifnull:$snippet:—"}},"searchText":"#tpl:{criterion} {file} {snippet}"}],"emptyHint":"未检出模糊测试活动（0 分）时无证据明细；NA 仓库（gcheck 无法运行）同样无明细数据"}',
1, 'ai-assisted', NOW());

-- 15 SECURITY_POLICY 安全策略（三项独立加分；无 SECURITY.md 时隐藏三检测明细，仅展示未检出说明，依赖引擎 has_file hook）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SECURITY_POLICY',
'{"rule":{"brief":"检查仓库是否提供安全政策文档 SECURITY.md（检查 .gitcode/、根目录、docs/ 等位置），并对文档内容做三项检测：联系链接、漏洞披露信息、自由文本说明。","formula":"无 SECURITY.md = 0 分；有 SECURITY.md 时三项独立加分：联系链接 +6、漏洞披露信息 +1、自由文本说明 +3（满分 10）","conditions":[{"label":"联系链接（+6 分）","value":"文档包含邮箱或 URL"},{"label":"漏洞披露信息（+1 分）","value":"文档包含漏洞报告相关说明（report / vulnerability / disclosure / exploit / CVE 等关键词）"},{"label":"自由文本说明（+3 分）","value":"文档包含实质性文本内容"}],"notes":[]},"definition":{"brief":"衡量仓库是否公开了安全策略文档（SECURITY.md），并考察文档质量：漏洞披露说明、联系方式、实质内容三项独立检测。","purpose":"安全策略让安全研究者知道往哪报告漏洞、能期待怎样的响应，是漏洞负责任披露机制的基础设施。","details":[{"label":"数据来源","value":"仓库文件树扫描（.gitcode/、根目录、docs/ 等位置）"},{"label":"检查对象","value":"SECURITY.md 标准命名文件 + 文档内容三项检测"},{"label":"参考标准","value":"对齐 OSSF Scorecard security-policy 思想"}],"notes":[]},"params":{"s1":"1","s6":"6","s3":"3"},"summary":[{"label":"联系链接","when":"has_file = 1","value":"#bool:$link:满足:未满足","level":"#bool:$link:success:error"},{"label":"漏洞披露信息","when":"has_file = 1","value":"#bool:$disclosure:满足:未满足","level":"#bool:$disclosure:success:error"},{"label":"自由文本说明","when":"has_file = 1","value":"#bool:$free_text:满足:未满足","level":"#bool:$free_text:success:error"},{"key":"sat","hidden":true,"when":"has_file = 1","value":"#sat:$disclosure,$link,$free_text"},{"label":"已满足","when":"has_file = 1","value":"#tpl:{s.sat} / 3","level":"#lt:$s.sat:3:error"}],"failNote":"#tpl:评分：三项独立加分 —— 联系链接 +6、漏洞披露信息 +1、自由文本说明 +3 → score = {score}。本指标既不是档位判定，也不是按比例扣分","failEmptyText":"全部满足：仓库内已检出 SECURITY.md，三项检测（联系链接 / 漏洞披露信息 / 自由文本说明）全部满足","dataNote":"三项独立加分：联系链接 +6、漏洞披露信息 +1、自由文本说明 +3。无 SECURITY.md 时按口径记 0 分并参与汇聚（进分母），不是 NA；此时三项检测无执行前提，不展示检测明细，仅展示未检出说明。","failItems":[{"when":"has_file = 0","title":"未检出 SECURITY.md 文件","fields":[{"label":"检索路径","value":".gitcode/SECURITY.md、SECURITY.md、docs/SECURITY.md、security.md"},{"label":"判定","value":"未检出","level":"error"}],"reason":"仓库内未检出 SECURITY.md 文件，三项检测（联系链接 / 漏洞披露信息 / 自由文本说明）无执行前提，未执行，按口径记 0 分","searchText":"SECURITY.md"},{"when":"has_file = 1 && disclosure = 0","title":"未满足：漏洞披露信息","fields":[{"label":"检测项","value":"漏洞披露信息"},{"label":"加分数","value":"#tpl:+{p.s1}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出漏洞披露信息，+1 未得分","searchText":"漏洞披露"},{"when":"has_file = 1 && link = 0","title":"未满足：联系链接","fields":[{"label":"检测项","value":"联系链接"},{"label":"加分数","value":"#tpl:+{p.s6}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出联系链接，+6 未得分","searchText":"联系链接"},{"when":"has_file = 1 && free_text = 0","title":"未满足：自由文本说明","fields":[{"label":"检测项","value":"自由文本说明"},{"label":"加分数","value":"#tpl:+{p.s3}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出自由文本安全说明，+3 未得分","searchText":"自由文本"}],"groups":[{"key":"check","label":"检测项","when":"has_file = 1","columns":[{"label":"检测项","key":"item","type":"text"},{"label":"结果","key":"result","type":"text"},{"label":"加分","key":"score","type":"number"}],"rows":[{"item":"联系链接","ok":"$link","score":"#tpl:+{p.s6}"},{"item":"漏洞披露信息","ok":"$disclosure","score":"#tpl:+{p.s1}"},{"item":"自由文本说明","ok":"$free_text","score":"#tpl:+{p.s3}"}],"cellOf":{"item":{"text":"$item"},"result":{"text":"#bool:$ok:满足:未满足","level":"#bool:$ok:success:error"},"score":{"text":"$score"}},"searchText":"#tpl:{item}"}]}',
1, 'ai-assisted', NOW());

-- 16 VULNS 已知漏洞（致命/高危/中危/低危 分档计数卡）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('VULNS',
'{"rule":{"brief":"检查漏洞管理平台-漏洞视图中该仓库是否存在已超期且未关闭的漏洞，按严重度扣分。已关闭、已拒绝的漏洞不计入。","formula":"得分 = 10 − (致命×10 + 高危×5 + 中危×2 + 低危×1)，最低 0 分","conditions":[{"label":"致命","value":"每个扣 10 分"},{"label":"高危","value":"每个扣 5 分"},{"label":"中危","value":"每个扣 2 分"},{"label":"低危","value":"每个扣 1 分（严重度未标注的按低危计）"}],"notes":["超期判定 = 计划修复时间已过且仍未关闭"]},"definition":{"brief":"衡量漏洞管理平台中本仓库存量漏洞的修复及时性：已超期且未关闭的漏洞越多、严重度越高，扣分越多。","purpose":"推动团队在承诺的修复期限内关闭已知漏洞，避免漏洞长期滞留演变成安全债务。","details":[{"label":"数据来源","value":"漏洞管理平台（漏洞单的状态、严重度、计划修复时间）"},{"label":"统计口径","value":"已超期且未关闭的漏洞；已关闭、已拒绝的不计入"},{"label":"超期判定","value":"计划修复时间已过且仍未关闭"}],"notes":[]},"params":{"priceCritical":"10","priceHigh":"5","priceMedium":"2","priceLow":"1"},"summary":[{"key":"total","label":"超期未关闭漏洞","value":"$overdue_count","level":"#ge:$overdue_count:1:error"},{"label":"致命","value":"$deduct_detail.critical","level":"#ge:$deduct_detail.critical:1:critical"},{"label":"高危","value":"$deduct_detail.high","level":"#ge:$deduct_detail.high:1:error"},{"label":"中危","value":"$deduct_detail.medium","level":"#ge:$deduct_detail.medium:1:warning"},{"label":"低危","value":"$deduct_detail.low"},{"key":"subCritical","hidden":true,"value":"#mul:$deduct_detail.critical,$p.priceCritical"},{"key":"subHigh","hidden":true,"value":"#mul:$deduct_detail.high,$p.priceHigh"},{"key":"subMedium","hidden":true,"value":"#mul:$deduct_detail.medium,$p.priceMedium"},{"key":"subLow","hidden":true,"value":"#mul:$deduct_detail.low,$p.priceLow"}],"failNote":"#tpl:评分：max(0, 10 − {deduct_detail.deduct_points}) = {score}　｜　扣分构成：致命 {deduct_detail.critical}×{p.priceCritical} + 高危 {deduct_detail.high}×{p.priceHigh} + 中危 {deduct_detail.medium}×{p.priceMedium} + 低危 {deduct_detail.low}×{p.priceLow} = {deduct_detail.deduct_points}　｜　漏洞的逐条清单在「全部扫描数据」里","failEmptyText":"全部满足：漏洞平台已覆盖本仓库，且无超期未关闭漏洞","dataNote":"本指标只统计「超期且未关闭」的漏洞：计划完成时间已过 且 状态非关闭态（closed / rejected 均视为关闭）。严重度为 None/空时按「低危」计入。明细按扣分降序排列。","failItems":[{"when":"deduct_detail.critical>=1","title":"#tpl:致命漏洞 {deduct_detail.critical} 个","fields":[{"label":"严重度","value":"致命","level":"critical"},{"label":"数量","value":"$deduct_detail.critical"},{"label":"单价扣分","value":"#tpl:-{p.priceCritical}"},{"label":"小计扣分","value":"#tpl:-{s.subCritical}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的致命漏洞 {deduct_detail.critical} 个，每个扣 {p.priceCritical} 分，小计扣 {s.subCritical} 分","deduct":"#tpl:-{s.subCritical}","searchText":"#tpl:致命 {deduct_detail.critical} 个 扣{p.priceCritical} 小计{s.subCritical}"},{"when":"deduct_detail.high>=1","title":"#tpl:高危漏洞 {deduct_detail.high} 个","fields":[{"label":"严重度","value":"高危","level":"error"},{"label":"数量","value":"$deduct_detail.high"},{"label":"单价扣分","value":"#tpl:-{p.priceHigh}"},{"label":"小计扣分","value":"#tpl:-{s.subHigh}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的高危漏洞 {deduct_detail.high} 个，每个扣 {p.priceHigh} 分，小计扣 {s.subHigh} 分","deduct":"#tpl:-{s.subHigh}","searchText":"#tpl:高危 {deduct_detail.high} 个 扣{p.priceHigh} 小计{s.subHigh}"},{"when":"deduct_detail.medium>=1","title":"#tpl:中危漏洞 {deduct_detail.medium} 个","fields":[{"label":"严重度","value":"中危","level":"warning"},{"label":"数量","value":"$deduct_detail.medium"},{"label":"单价扣分","value":"#tpl:-{p.priceMedium}"},{"label":"小计扣分","value":"#tpl:-{s.subMedium}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的中危漏洞 {deduct_detail.medium} 个，每个扣 {p.priceMedium} 分，小计扣 {s.subMedium} 分","deduct":"#tpl:-{s.subMedium}","searchText":"#tpl:中危 {deduct_detail.medium} 个 扣{p.priceMedium} 小计{s.subMedium}"},{"when":"deduct_detail.low>=1","title":"#tpl:低危漏洞 {deduct_detail.low} 个","fields":[{"label":"严重度","value":"低危"},{"label":"数量","value":"$deduct_detail.low"},{"label":"单价扣分","value":"#tpl:-{p.priceLow}"},{"label":"小计扣分","value":"#tpl:-{s.subLow}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的低危漏洞 {deduct_detail.low} 个，每个扣 {p.priceLow} 分，小计扣 {s.subLow} 分","deduct":"#tpl:-{s.subLow}","searchText":"#tpl:低危 {deduct_detail.low} 个 扣{p.priceLow} 小计{s.subLow}"}],"groups":[{"key":"vuln","label":"超期未关闭漏洞","columns":[{"label":"issue","key":"issue","type":"text"},{"label":"CVE 编号","key":"cve","type":"text"},{"label":"严重度","key":"sev","type":"text"},{"label":"计划完成时间","key":"plan","type":"text"},{"label":"状态","key":"status","type":"text"},{"label":"扣分","key":"deduct","type":"number"}],"rowsFrom":"$vuln_detail","cellOf":{"issue":{"text":"$issue_id","href":"#href:https://gitcode.com/{repoPath}/issues/{issue_id}"},"cve":{"text":"$cve_num"},"sev":{"text":"$severity","level":"#map:$severity:致命:critical,Critical:critical,critical:critical,高危:error,High:error,high:error,中危:warning,Medium:warning,medium:warning,*:"},"plan":{"text":"$plan_closed_time"},"status":{"text":"$status"},"deduct":{"text":"#map:$severity:critical:-10,Critical:-10,致命:-10,high:-5,High:-5,高危:-5,medium:-2,Medium:-2,中危:-2,low:-1,Low:-1,低危:-1,None:-1,*:-1","level":"#map:$severity:critical:critical,Critical:critical,致命:critical,high:error,High:error,高危:error,*:"}},"rowLevel":"#map:$severity:critical:critical,Critical:critical,致命:critical,high:error,High:error,高危:error,*:","searchText":"#tpl:{issue_id} {cve_num} {severity} {plan_closed_time} {status}"}]}',
1, 'ai-assisted', NOW());

-- 17 MAINTAINED 项目维护（2026-10-08 接入 commit/issue 明细清单，各取最近 20 条）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('MAINTAINED',
'{"rule":{"brief":"检查仓库近 90 天的维护活跃度 = 默认分支 commit 数 + 新建 issue 数。","formula":"得分 = 10 × (commit 数 + issue 数) / 13，上限 10 分。","conditions":[{"label":"commit","value":"默认分支近 90 天commit数量"},{"label":"issue","value":"近 90 天新建 issue 数"}],"naCondition":"仓库已归档、或创建时间不足 90 天（尚在孵化期）时，本指标不参评。","notes":[]},"definition":{"brief":"衡量仓库近 90 天的维护活跃度：默认分支 commit 数与新建 issue 数合计对照活跃门槛。","purpose":"长期无人维护的仓库意味着缺陷得不到修复、依赖得不到升级，是供应链风险的高发区。","details":[{"label":"数据来源","value":"仓库 commit 日志与 issue 处理记录"},{"label":"统计口径","value":"近 90 天默认分支 commit 数 + 新建 issue 数"},{"label":"参考标准","value":"对齐 OSSF Scorecard maintained 思想"}],"notes":["仓库已归档或创建不足 90 天（孵化期）时不参评"]},"params":{"threshold":"13"},"summary":[{"key":"commit","label":"近 90 天 commit","value":"$commit_cnt_90d"},{"key":"issue","label":"近 90 天 issue","value":"$issue_cnt_90d"},{"key":"total","hidden":true,"value":"#add:$commit_cnt_90d,$issue_cnt_90d"},{"key":"gap","hidden":true,"value":"#sub:$p.threshold,$s.total"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"},{"label":"合计 / 门槛","value":"#tpl:{s.total} / {p.threshold}","level":"#lt:$s.total:$p.threshold:error"},{"label":"仓库创建时间","value":"#ifnull:$repo_created:—"}],"failNote":"#tpl:评分：min(10, 10 × {s.total} / {p.threshold}) = {score}　｜　近 90 天 commit + issue 合计 {s.total}，门槛 {p.threshold}","failEmptyText":"全部满足：近 90 天 commit + issue 合计已达到门槛，无扣分","dataNote":"统计近 90 天的 commit 与 issue 活跃度，合计达到门槛即满分，未达门槛按比例计分（门槛可在 params.threshold 调整）。仓库已归档时本指标 NA。明细清单按时间倒序展示最近 20 条 commit 与 issue。","failItems":[{"when":"total<@p.threshold","title":"近 90 天活跃度未达门槛","fields":[{"label":"commit 数(90d)","value":"$commit_cnt_90d"},{"label":"issue 数(90d)","value":"$issue_cnt_90d"},{"label":"合计","value":"#tpl:{s.total}"},{"label":"门槛","value":"#tpl:{p.threshold}"},{"label":"差额","value":"#tpl:-{s.gap}","level":"error"}],"reason":"#tpl:未满足：近 90 天 commit + issue 合计 {s.total}，低于门槛 {p.threshold}，还差 {s.gap} 条","formula":"#tpl:score = min(10, 10 × {s.total} / {p.threshold}) = {score}","deduct":"#tpl:-{s.deduct}","searchText":"活跃度 门槛 commit issue"}],"groups":[{"key":"commits","label":"近 90 天 commit（最近 20 条）","columns":[{"label":"时间","key":"time","type":"text"},{"label":"作者","key":"author","type":"text"},{"label":"提交说明","key":"title","type":"text"},{"label":"链接","key":"link","type":"text"}],"rowsFrom":"$commit_rows","cellOf":{"time":{"text":"$commit_time"},"author":{"text":"#tpl:{author_name}（{author_username}）"},"title":{"text":"$commit_title"},"link":{"text":"查看","href":"#href:https://gitcode.com/{repoPath}/commit/{commit_hash}"}},"searchText":"#tpl:{author_name} {commit_title}"},{"key":"issues","label":"近 90 天 issue（最近 20 条）","columns":[{"label":"编号","key":"num","type":"text"},{"label":"状态","key":"state","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"创建时间","key":"time","type":"text"}],"rowsFrom":"$issue_rows","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"state":{"text":"#map:$state:open:开启,closed:已关闭,*:其他","level":"#map:$state:open:warning,closed:success,*:"},"title":{"text":"$title"},"creator":{"text":"$creator"},"time":{"text":"$created_at"}},"searchText":"#tpl:{title} {creator}"}],"emptyHint":"近 90 天无 commit / issue 活跃记录"}',
1, 'ai-assisted', NOW());

-- 18 CONTRIBUTORS 贡献者多样性（公司口径 v2：GitCode 用户资料 company 字段；公司内逐作者明细暂未采集）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CONTRIBUTORS',
'{"rule":{"brief":"检查最近 30 次已合入 PR 的作者（剔除机器人）来自多少个不同公司，且这些公司中是否有活跃作者（近 30 次 PR 中个人贡献 ≥ 5 个）。“公司”取自 GitCode 用户资料的公司字段。","formula":"得分 = 10 × N / 3，上限 10 分（N = 存在至少 1 名活跃作者的公司个数，3 个即满分）","conditions":[{"label":"活跃作者","value":"近 30 次已合入 PR 中该作者贡献 ≥ 5 个"},{"label":"N 值","value":"存在至少 1 名活跃作者的公司个数"},{"label":"公司归属","value":"GitCode 用户资料公司字段；未填写或账号已注销/改名的作者统一归入「未配置公司」，视为一个公司参与 N 值；华为系写法已归一为「华为技术有限公司」"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"近 30 次已合入 PR 为 0 时，本指标不参评。","notes":[]},"definition":{"brief":"衡量仓库贡献者来源公司的多样性：近 30 次已合入 PR 中，活跃作者覆盖的不同公司个数。","purpose":"单一公司依赖意味着 bus factor 风险：一旦该公司退出，项目可能失去维护能力；多公司参与是社区健康度的信号。","details":[{"label":"数据来源","value":"GitCode 用户资料 company 字段（users/:username 接口，T7 每日采集）"},{"label":"统计口径","value":"N = 存在至少 1 名活跃作者（近 30 次 PR 中贡献 ≥ 5 个）的公司个数，剔除机器人；未填写公司或账号已注销/改名的作者统一归入虚拟公司「未配置公司」，与真实公司平权参与 N 值"},{"label":"计分","value":"N ≥ 3 即满分"}],"notes":[]},"params":{"minOrgs":"3"},"summary":[{"label":"作者数（去重）","value":"$author_count"},{"label":"公司数","value":"$n_orgs"},{"key":"n","label":"达标公司数 N","value":"#count:$qualified_orgs","level":"#lt:$s.n:$p.minOrgs:error"},{"label":"达标门槛","value":"#tpl:N ≥ {p.minOrgs}"}],"failNote":"#tpl:评分：min(10, 10 × 达标公司数 {s.n} / {p.minOrgs}) = {score}　｜　达标公司 = 该公司内存在至少 1 名作者近 30 次 PR 数达标　｜　因 min(10,…) 封顶，卡片不显示逐条扣分","failEmptyText":"全部满足：达标公司数已达门槛，贡献者多样性足够","dataNote":"贡献者口径为「近 30 次已合入 PR 的作者」（非全量贡献者）。公司取自 GitCode 用户资料的 company 字段，当前填写率较低（2026-10 实测约 1.6%）；未填写或账号已注销/改名的作者统一归入虚拟公司「未配置公司」，视为一个公司参与 N 值（贡献者补填 GitCode 资料后即可浮出为真实公司）；华为系写法（huawei/hw/华为等）已归一为「华为技术有限公司」。","failItems":[{"when":"n<@p.minOrgs","title":"达标公司数未达门槛","fields":[{"label":"作者数（去重）","value":"$author_count"},{"label":"公司数","value":"$n_orgs"},{"label":"达标公司数 N","value":"#tpl:{s.n}","level":"error"},{"label":"达标门槛","value":"#tpl:N ≥ {p.minOrgs}"}],"reason":"#tpl:未满足：达标公司数 {s.n}，低于门槛 {p.minOrgs}","searchText":"公司 多样性"}],"groups":[{"key":"org","label":"达标公司","columns":[{"label":"公司","key":"org","type":"text"}],"rowsFrom":"$qualified_orgs","cellOf":{"org":{"text":"$this"}},"searchText":"$this"},{"key":"authors","label":"贡献者明细（近 30 次 PR）","columns":[{"label":"贡献者","key":"user","type":"text"},{"label":"公司","key":"org","type":"text"},{"label":"近30次PR","key":"pr_cnt","type":"text"}],"rowsFrom":"$authors","cellOf":{"user":{"text":"#tpl:{user}","href":"$url"},"org":{"text":"#ifnull:$org:未配置公司"},"pr_cnt":{"text":"#tpl:{pr_cnt}"}},"searchText":"#tpl:{user} {org}"}],"emptyHint":"贡献者明细为近 30 次已合入 PR 窗口内的全部作者（按 PR 数倒序）；达标公司清单仅列出存在活跃作者的公司；「未配置公司」= GitCode 资料未填 company 或账号已注销/改名的作者（视为一个公司参与 N 值）"}',
1, 'ai-assisted', NOW());
